    while node: s = str(node.val) + s; node = node.next
    return int(s or '0')
def mk_list(n):
    dummy = tail = ListNode()
    for ch in str(n)[::-1]:
        tail.next = ListNode(int(ch)); tail = tail.next
    return dummy.next
def add_two_numbers(l1, l2):
