def delete_duplicates(head):
    dummy = ListNode(next=head); cur = dummy
    while cur.next:
        if cur.next.next and cur.next.val == cur.next.next.val:
            v = cur.next.val
            while cur.next and cur.next.val == v:
                cur.next = cur.next.next
        else:
            cur = cur.next
    return dummy.next

def partition(head, x):
    lt = tl = ListNode(); ge = tg = ListNode()
    cur = head
    while cur:
        if cur.val < x:
            tl.next = cur; tl = tl.next
        else:
            tg.next = cur; tg = tg.next
        cur = cur.next
    tg.next = None
    tl.next = ge.next
    return lt.next

