class LNode:
    def __init__(self, k=0, v=0):
        self.key = k; self.val = v; self.prev = self.next = None
class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity; self.m = {}
        self.head = LNode(); self.tail = LNode()
        self.head.next = self.tail; self.tail.prev = self.head
    def _remove(self, n):
        n.prev.next = n.next; n.next.prev = n.prev
    def _add(self, n):
        p = self.tail.prev; p.next = n; n.prev = p
        n.next = self.tail; self.tail.prev = n
    def get(self, key):
        if key not in self.m: return -1
        n = self.m[key]; self._remove(n); self._add(n)
        return n.val
    def put(self, key, value):
        if key in self.m: self._remove(self.m[key])
        n = LNode(key, value); self.m[key] = n; self._add(n)
        if len(self.m) > self.cap:
            x = self.head.next; self._remove(x); del self.m[x.key]
